<?php $isField=!\App\Core\Auth::can('job.assign'); $checkinDistance=null;if($job['checkin_latitude']!==null&&$job['checkin_longitude']!==null&&$job['site_latitude']!==null&&$job['site_longitude']!==null){$earth=6371000.0;$dLat=deg2rad((float)$job['site_latitude']-(float)$job['checkin_latitude']);$dLng=deg2rad((float)$job['site_longitude']-(float)$job['checkin_longitude']);$a=sin($dLat/2)**2+cos(deg2rad((float)$job['checkin_latitude']))*cos(deg2rad((float)$job['site_latitude']))*sin($dLng/2)**2;$checkinDistance=$earth*2*atan2(sqrt($a),sqrt(1-$a));} $materialCost=(float)($cost['material_cost']??0);$expenseCost=(float)($cost['expense_cost']??0);$revenue=(float)($cost['revenue']??0);$totalCost=$materialCost+$expenseCost;$profit=$revenue-$totalCost; ?>
